//! r7 enums and static metadata, generated by build.rs from data/*.json.

pub use crate::identity::EnchantmentId;

/// Original-DLL pet-targeted plays throw in their player-only effects despite
/// CardModel.IsValidTarget accepting the pet. Keep predicate legality separate
/// from execution admission; never invent a successful outcome for these.
pub const ORIGINAL_PET_TARGET_FAULTS: &[CardId] = &[
    CardId::BelieveInYou, CardId::Constellation, CardId::Ignition,
    CardId::ImitationLearning, CardId::InterceptCard, CardId::Largesse,
    CardId::Soulbound, CardId::Tutor,
];

#[derive(Clone, Copy, Debug)]
pub struct CardInfo {
    pub cost: i32,
    pub card_type: CardType,
    pub target: TargetType,
    pub rarity: CardRarity,
    pub damage: Option<i32>,
    pub block: Option<i32>,
    pub upgraded: bool,
    pub keywords: u16,
    pub tags: &'static [CardTag],
    pub gen_combat: bool,
    pub gen_modifiers: bool,
    pub enchantments: &'static [(EnchantmentId, i32)],
    /// Effect vars in r7 dict insertion order.
    pub vars: &'static [(VarKey, i32)],
    pub x_cost: bool,
    pub star_cost: i32,
    pub star_x: bool,
    pub turn_end_in_hand: bool,
    pub replay: i32,
    pub single_turn_retain: bool,
    pub gains_block: bool,
    pub custom_playability: bool,
    pub custom_should_play: bool,
    /// C# `VisualCardPool.IsColorless` (data `visual_pool == COLORLESS`).
    pub visual_colorless: bool,
    /// `reference_card_entry(card_id)`: the .NET List<T>.Sort key before shuffles.
    pub entry: &'static str,
    pub upgradable: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct PotionInfo {
    pub id: &'static str,
    pub rarity: PotionRarity,
    pub usage: PotionUsageType,
    pub target: PotionTargetType,
    pub character_specific: bool,
    pub character_pool: Option<&'static str>,
    pub gen_combat: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct RelicInfo {
    pub rarity: RelicRarity,
    pub pool: RelicPool,
    pub stackable: bool,
    pub upon_pickup: bool,
    pub spawns_pets: bool,
    pub shops: bool,
    /// r7 RelicInstance hooks this relic overrides that can act inside a combat.
    pub combat_hooks: &'static [&'static str],
    /// `combat_hooks` as `Hook` bits (hooks outside the `Hook` enum have no bit).
    pub hook_mask: u128,
}

/// r7 power-class metadata. `hooks` has bit `Hook::x as u32` set when the class overrides it.
#[derive(Clone, Copy, Debug)]
pub struct PowerMeta {
    pub exists: bool,
    pub power_type: PowerType,
    pub stack_type: PowerStackType,
    pub instanced: bool,
    pub allow_negative: bool,
    pub temporary: bool,
    pub visible: bool,
    pub hooks: u128,
    /// r7 optional death methods: bit 0 before_death, 1 after_death, 2 on_ally_death.
    pub death: u8,
}

impl PowerMeta {
    pub const MISSING: PowerMeta = PowerMeta {
        exists: false, power_type: PowerType::Buff, stack_type: PowerStackType::Counter, instanced: false,
        allow_negative: false, temporary: false, visible: true, hooks: 0, death: 0,
    };
    #[inline]
    pub const fn listens(&self, hook: Hook) -> bool {
        self.hooks & (1u128 << hook as u32) != 0
    }
}

#[derive(Clone, Copy, Debug)]
pub struct IntentDef {
    pub kind: IntentType,
    pub damage: i32,
    pub hits: i32,
    pub cards: i32,
}

#[derive(Clone, Copy, Debug)]
pub struct BranchDef {
    pub target: u8,
    pub repeat: MoveRepeatType,
    pub max_times: i32,
    /// `None`: the r7 weight is a callable evaluated in the monster's Rust code.
    pub weight: Option<f64>,
    pub cooldown: i32,
}

#[derive(Clone, Copy, Debug)]
pub enum StateKind {
    Move { follow_up: Option<u8>, must_perform_once: bool, in_logs: bool, intents: &'static [IntentDef] },
    Random { branches: &'static [BranchDef] },
    Conditional { targets: &'static [u8] },
}

#[derive(Clone, Copy, Debug)]
pub struct StateDef {
    pub id: &'static str,
    pub kind: StateKind,
}

/// Monster factory bands: 0 = A0-7, 1 = A9-10, 2 = A8.
#[derive(Clone, Copy, Debug)]
pub struct MonsterDef {
    pub monster_id: &'static str,
    pub hp: (i32, i32),
    pub initial: u8,
    pub states: &'static [StateDef],
    pub powers: &'static [(PowerId, i32)],
}

include!(concat!(env!("OUT_DIR"), "/gen_tables.rs"));

#[inline]
pub fn power_meta(id: PowerId) -> &'static PowerMeta {
    &POWER_META[id.index()]
}

/// `asc_band`: 0 below Tough, 2 at Tough only, 1 at Deadly and above.
#[inline]
pub fn monster_def(kind: MonsterKind, asc_band: usize) -> &'static MonsterDef {
    &MONSTER_DEFS[kind.index()][asc_band]
}

/// Factory metadata of `create_card(card_id, upgraded)`; `None` where r7 has no factory.
#[inline]
pub fn card_info(id: CardId, upgraded: bool) -> Option<&'static CardInfo> {
    CARD_INFO[id.index()][upgraded as usize].as_ref()
}
